// Multiple classes in one file for the runnable demo.
package com.bank.transfer;

import java.math.BigDecimal;
import java.util.logging.*;

public class TransferQueueDemo {
    private static final Logger log = Logger.getLogger(TransferQueueDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Rajesh's scheduled transfer queue: T1 -> T2 -> T3 -> T4 -> T5
        ScheduledTransfer head = build(
            new String[]{"T1", "T2", "T3", "T4", "T5"},
            new String[]{"1000", "2000", "3000", "4000", "5000"});

        log.info("Rajesh (SAV2001) wants to cancel the 2nd-from-last scheduled transfer");
        TransferQueueService service = new TransferQueueService();
        ScheduledTransfer result = service.removeNthFromEnd(head, 2);

        for (ScheduledTransfer n = result; n != null; n = n.next) {
            final ScheduledTransfer cur = n;
            log.info(() -> "Remaining -> " + cur.transferId + " amount Rs." + cur.amount);
        }
        log.info("Scheduled transfer queue updated successfully");
    }

    private static ScheduledTransfer build(String[] ids, String[] amounts) {
        ScheduledTransfer dummy = new ScheduledTransfer(null, BigDecimal.ZERO);
        ScheduledTransfer tail = dummy;
        for (int i = 0; i < ids.length; i++) {
            tail.next = new ScheduledTransfer(ids[i], new BigDecimal(amounts[i]));
            tail = tail.next;
        }
        return dummy.next;
    }
}

