class ScheduledTransfer {
    String transferId;
    BigDecimal amount;
    ScheduledTransfer next;

    ScheduledTransfer(String transferId, BigDecimal amount) {
        this.transferId = transferId;
        this.amount = amount;
    }
}

// ─── Would be in service/TransferQueueService.java ───
class TransferQueueService {
    private static final Logger log = Logger.getLogger(TransferQueueService.class.getName());

    // Remove the Nth node from the end in a single pass. O(n) time, O(1) space.
    ScheduledTransfer removeNthFromEnd(ScheduledTransfer head, int n) {
        ScheduledTransfer dummy = new ScheduledTransfer(null, BigDecimal.ZERO);
        dummy.next = head;
        ScheduledTransfer fast = dummy;
        ScheduledTransfer slow = dummy;

        // Advance fast by n+1 steps, validating N against the list length
        for (int i = 0; i <= n; i++) {
            if (fast == null) {
                log.warning(() -> "N=" + n + " exceeds queue length; nothing removed");
                return head;  // defensive: N too large
            }
            fast = fast.next;
        }

        // Move both until fast falls off the end
        while (fast != null) {
            fast = fast.next;
            slow = slow.next;
        }

        // slow now sits right before the target; unlink it
        final String removedId = slow.next.transferId;
        log.info(() -> "Removing scheduled transfer " + removedId);
        slow.next = slow.next.next;
        return dummy.next;
    }
}

